  "update.afterBackupOrphans":
    "Docker giữ lại ảnh mà container chạy trước đó, giờ không còn thẻ, và Unraid liệt kê nó là ảnh mồ côi. Đó là phần còn lại bình thường của một lần cập nhật thành công, không phải dấu vết của lần thất bại, và cũng chính là thứ cần để quay nhanh về ảnh trước. Nếu bạn không muốn giữ nó, công tắc “Xóa image cũ sau khi cập nhật” trong Cài đặt, Lịch trình, Cập nhật sau khi sao lưu sẽ xoá ảnh bị thay thế ngay sau khi cập nhật.",
