  "breakdown.title": "Dung lượng theo thư mục",
  "breakdown.hint": "Những gì chiếm chỗ trong bản sao lưu mới nhất, lớn nhất trước, và phần mà lần sao lưu gần nhất mang vào là mới hoặc đã thay đổi. Tệp đã thay đổi được tính cả kích thước, vì restic không cho biết phần nào đã đổi. Kích thước là kích thước tệp trước khi khử trùng lặp và nén. BombVault đọc chúng từ chỉ mục của kho mà không đọc tệp, và cập nhật sau mỗi lần sao lưu.",
