  "whatsNew.instancesChecking": "Ngay sau khi BombVault khởi động, thẻ hiển thị Đang kiểm tra cho đến khi phiên bản của nó quay lại, thay vì trông như đã biến mất.",
  "whatsNew.pairingInactive": "Trang Ghép nối hiển thị máy chủ đã tắt và điện thoại đã đóng ứng dụng ở trạng thái Không hoạt động, kèm thời điểm thấy lần cuối.",
