  "whatsNew.ownFolderMove": "Thư mục riêng của một phần có thể chuyển đến một trong các đích của bạn và dùng thông tin đăng nhập cùng chế độ bảo vệ của đích đó. Nhiều phần chuyển trong một bước.",
