  "runReason.restoredWithoutRuntime": "đã khôi phục mà không có GPU hoặc runtime của container",
  "runReason.restoredWithoutLinks": "đã khôi phục mà không có liên kết tới các container không chạy",
  "runReason.containersNotBack": "một số container không khởi động lại",
  "dbdump.toggle": "Kết xuất cơ sở dữ liệu trước mỗi lần sao lưu",
  "dbdump.toggleHint": "BombVault đã nhận ra container này là cơ sở dữ liệu {engine}. Trước mỗi lần sao lưu, nó yêu cầu máy chủ đang chạy một bản kết xuất SQL đầy đủ và cất nó thành một điểm khôi phục riêng, thẳng vào kho sao lưu, không ghi tệp nào lên ổ đĩa của bạn. Việc khôi phục dùng bản sao lưu tệp được lấy sau khi container dừng; bản kết xuất là bản sao thứ hai mà bạn có thể tải về hoặc nhập lại. Một bản kết xuất thất bại không bao giờ làm hỏng bản sao lưu, nó hiện ra như một lần chạy thất bại riêng.",
  "dbdump.toggleHintLabel": "Nhãn container bombvault.dbdump bật kết xuất cho cơ sở dữ liệu {engine} này. Trước mỗi lần sao lưu, BombVault yêu cầu máy chủ đang chạy một bản kết xuất SQL đầy đủ và cất nó thành một điểm khôi phục riêng. Một bản kết xuất thất bại không bao giờ làm hỏng bản sao lưu, nó hiện ra như một lần chạy thất bại riêng.",
  "dbdump.toggleHintOnlyCopy": "Trước mỗi lần sao lưu, BombVault yêu cầu máy chủ {engine} đang chạy này một bản kết xuất SQL đầy đủ và cất nó thành một điểm khôi phục riêng. Với container này, bản kết xuất là bản sao nhất quán duy nhất của cơ sở dữ liệu: thư mục dữ liệu của nó hoặc được chép khi máy chủ đang chạy, hoặc không nằm trong bản sao lưu nào. Hãy để kết xuất bật. Một bản kết xuất thất bại không bao giờ làm hỏng bản sao lưu, nó hiện ra như một lần chạy thất bại riêng.",
  "dbdump.toggleHintUnknown": "Trước mỗi lần sao lưu, BombVault yêu cầu máy chủ {engine} đang chạy này một bản kết xuất SQL đầy đủ và cất nó thành một điểm khôi phục riêng. Không xác định được container này giữ thư mục dữ liệu ở đâu, nên không rõ bản sao lưu tệp có chứa thứ gì dùng được hay không. Bản kết xuất là bản sao bạn có thể trông cậy. Hãy để nó bật. Một bản kết xuất thất bại không bao giờ làm hỏng bản sao lưu, nó hiện ra như một lần chạy thất bại riêng.",
  "dbdump.lookalikeHint": "Container này trông giống cơ sở dữ liệu {engine}, nhưng BombVault không biết chắc image của nó. Hãy bật kết xuất nếu đúng vậy; nếu sau đó thất bại thì image không theo các thiết lập thường gặp và bạn có thể tắt lại.",
  "dbdump.engineLabel": "Loại cơ sở dữ liệu",
  "dbdump.labelOff": "Bị tắt bởi nhãn container bombvault.dbdump=false.",
  "dbdump.globalOff": "Kết xuất cơ sở dữ liệu tự động đang tắt cho mọi container trong Cài đặt, Chung.",
  "dbdump.offConfirmLive": "Tắt kết xuất cho cơ sở dữ liệu này? Thư mục dữ liệu của nó được chép khi máy chủ đang chạy, nên không có kết xuất thì không tồn tại bản sao nhất quán nào.",
  "dbdump.offConfirmNone": "Tắt kết xuất cho cơ sở dữ liệu này? Thư mục dữ liệu của nó không nằm trong bản sao lưu nào, nên không có kết xuất thì không giữ lại được gì.",
  "dbdump.offConfirmUnknown": "Tắt kết xuất cho cơ sở dữ liệu này? BombVault không xác định được thư mục dữ liệu của nó ở đâu, nên không rõ bản sao lưu nào có chứa thứ dùng được hay không.",
  "dbdump.coverageStopped": "Thư mục dữ liệu: được lưu khi container đã dừng.",
  "dbdump.coverageLive": "Thư mục dữ liệu: được chép khi máy chủ đang chạy. Bản kết xuất là bản sao nhất quán.",
  "dbdump.coverageNone": "Thư mục dữ liệu: không nằm trong bản sao lưu nào. Bản kết xuất là bản sao duy nhất.",
  "dbdump.coverageUnknown": "Thư mục dữ liệu: không xác định được. Hãy để kết xuất bật.",
  "dbdump.coverageHint": "Cơ sở dữ liệu ghi vào tệp của nó liên tục. Bản chép các tệp đó chỉ đáng tin khi máy chủ đã dừng trong lúc chép, và đó chính là điều BombVault làm với các thư mục nằm trong bản sao lưu của container. Thư mục trong một dự án compose hay một bộ thư mục được chép khi máy chủ đang chạy, còn thư mục ngoài appdata thì không được chép chút nào. Trong những trường hợp đó, bạn sẽ khôi phục từ bản kết xuất.",
  "dbdump.hookOverlap": "Lệnh trước khi sao lưu của container này đã tự kết xuất một cơ sở dữ liệu. Hãy tắt một trong hai, nếu không cơ sở dữ liệu sẽ bị kết xuất hai lần.",
