  "dbdump.busyDumping": "Đang kết xuất cơ sở dữ liệu...",
  "dbdump.busySaving": "Đang lưu bản kết xuất cơ sở dữ liệu...",
  "dbdump.busyImporting": "Đang nhập bản kết xuất cơ sở dữ liệu...",
  "dbdump.updateWarn": "Đây là cơ sở dữ liệu. Việc cập nhật image có thể đưa nó lên một phiên bản lớn mới từ chối thư mục dữ liệu cũ. Bản kết xuất lấy ngay trước khi cập nhật khi đó có thể nhập vào phiên bản mới từ bảng Bản sao lưu.",
  "dbdump.updateWarnSameMajor": "Đây là cơ sở dữ liệu. Việc cập nhật image có thể đưa nó lên một phiên bản lớn mới. MySQL và MariaDB chỉ nhập bản kết xuất vào đúng phiên bản lớn mà nó được lấy ra, nên nếu phiên bản mới từ chối thư mục dữ liệu cũ, hãy đưa image về phiên bản trước và nhập ở đó bản kết xuất lấy ngay trước khi cập nhật.",
  "dbdump.stackRestoreWarn": "Dữ liệu của {names} được chép khi stack đang chạy. Sau khi khôi phục, hãy nhập bản kết xuất cơ sở dữ liệu mới nhất của chúng trước khi dùng các ứng dụng.",
  "dbdump.introNotice": "BombVault kết xuất các cơ sở dữ liệu nó nhận ra trước mỗi lần sao lưu, thành các điểm khôi phục riêng. Nhận ra ở đây: {n} cơ sở dữ liệu, cái đầu tiên là {name}. Bạn có thể tắt việc này theo từng container trên thẻ của nó, hoặc cho mọi container trong Cài đặt.",
  "dbdump.fixAuth": "Hãy kiểm tra các biến mật khẩu trên chính container cơ sở dữ liệu (ví dụ POSTGRES_PASSWORD, MARIADB_ROOT_PASSWORD hoặc MYSQL_ROOT_PASSWORD, hoặc bản _FILE của chúng). Bản kết xuất dùng đúng những biến đó.",
  "dbdump.fixPrivileges": "Bản kết xuất chỉ đăng nhập được với tư cách người dùng ứng dụng, vốn thiếu một quyền mà nó cần. Hãy đặt cho container một mật khẩu root thật thay vì mật khẩu ngẫu nhiên.",
  "dbdump.fixUnreachable": "Máy chủ cơ sở dữ liệu không trả lời trên socket cục bộ của nó. Hãy xem nhật ký container, có thể nó còn đang khởi động hoặc đã sập.",
  "dbdump.fixNotRunning": "Container đang tạm dừng hoặc đang khởi động lại khi bản sao lưu chạy. Nếu nó cứ khởi động lại, hãy xem nhật ký của nó.",
  "dbdump.fixNoClient": "Image không có công cụ kết xuất. Hãy dùng image chính thức, hoặc tắt kết xuất cho container này.",
  "dbdump.fixSecret": "Người dùng của container không đọc được tệp mật khẩu nêu trong biến _FILE. Hãy kiểm tra đường dẫn và quyền của nó.",
  "dbdump.fixNoCredentials": "Thiết lập của container không có mật khẩu root lẫn người dùng có cơ sở dữ liệu. Hãy đặt MARIADB_ROOT_PASSWORD (hoặc MYSQL_ROOT_PASSWORD), hoặc một người dùng và một cơ sở dữ liệu.",
  "dbdump.fixNeedsUpgrade": "Các bảng hệ thống của cơ sở dữ liệu đến từ phiên bản cũ hơn. Hãy thêm biến MARIADB_AUTO_UPGRADE với giá trị 1 vào container rồi khởi động lại, hoặc chạy mariadb-upgrade một lần bên trong container.",
  "dbdump.fixTimeout": "Bản kết xuất đã chạm giới hạn thời gian. Với cơ sở dữ liệu rất lớn, hãy thêm biến DB_DUMP_MAX_HOURS vào container BombVault (Unraid: sửa container, Add another Path, Port, Variable), ví dụ 12.",
  "dbdump.fixBackupCap": "Cả lần sao lưu đã chạm BACKUP_MAX_HOURS trong khi bản kết xuất còn chạy. Hãy tăng BACKUP_MAX_HOURS trên container BombVault.",
  "dbdump.fixStalled": "Bản kết xuất ngừng tiến triển, thường vì ứng dụng đang giữ một khoá. Nó sẽ được thử lại ở lần sao lưu sau.",
  "dbdump.fixDumpData": "Công cụ kết xuất dừng lại với thông báo được hiển thị. Nó sẽ được thử lại ở lần sao lưu sau; nếu vẫn thất bại, thông báo đó nêu nguyên nhân.",
  "dbdump.fixDocker": "Docker đã không chạy lệnh kết xuất. Thường là container bị dừng, tạm dừng hoặc tạo lại trong lúc bản sao lưu đang khởi động. Nó sẽ được thử lại ở lần sao lưu sau; nếu cứ tiếp diễn, hãy kiểm tra dịch vụ Docker và quyền truy cập của BombVault.",
  "dbdump.fixRepository": "Kho sao lưu không nhận bản kết xuất, hoặc lưu ít byte hơn số đã kết xuất. Hãy kiểm tra kho trong Cài đặt, Đích sao lưu; bản kết xuất sẽ được thử lại ở lần sao lưu sau.",
  "dbdump.fixLeftover": "Một bản kết xuất hỏng không xoá được khỏi kho. Hãy xoá nó khỏi danh sách kết xuất trong bảng Bản sao lưu.",
  "dbdump.fixHelper": "Bộ trợ giúp kết xuất của BombVault kết thúc mà không có kết quả. Nếu lặp lại, hãy mở một báo cáo và đính kèm gói chẩn đoán.",
  "dbdump.listTitle": "Bản kết xuất cơ sở dữ liệu",
  "dbdump.listHint": "Mỗi bản kết xuất là một bản xuất SQL đầy đủ lấy từ cơ sở dữ liệu đang chạy, ngay trước khi sao lưu nó. BombVault không bao giờ tự nạp lại bản kết xuất: khôi phục vùng chứa sẽ trả lại các tệp của nó, và nếu các tệp đó được lưu khi vùng chứa đã dừng thì chúng là bản sao mới hơn. Hãy dùng bản kết xuất khi các tệp đó không dùng được: chúng được chép khi máy chủ đang chạy hoặc không được chép, cơ sở dữ liệu đã chuyển sang phiên bản chính mới, hoặc thư mục dữ liệu bị hỏng. Việc nhập đặt bản kết xuất vào một cơ sở dữ liệu trống vừa khởi động và giữ thư mục dữ liệu cũ bên cạnh. Tệp .sql đầy đủ kết thúc bằng dòng chú thích \"complete\".",
  "dbdump.none": "Chưa có bản kết xuất cơ sở dữ liệu nào.",
