  "offsite.prune.title": "5 · Dọn bớt off-site",
  "offsite.prune.info": "Bước này chỉ cho biết điều gì đang diễn ra, nó không thiết lập gì cả. Việc bản sao này có được dọn bớt hay không do append-only ở bước 4 và các giá trị giữ lại trong Cài đặt, Đích sao lưu quyết định. Nếu vẫn muốn dọn bớt một bản sao append-only, hãy chạy restic forget --prune ở phía lưu trữ, hoặc theo lịch riêng của nó, hoặc bằng cách dựng tạm một máy chủ REST thứ hai không bật append-only, dọn qua nó rồi tắt đi.",
