  "mcp.oauthHint": "Dành cho ChatGPT, Claude trên claude.ai và các dịch vụ khác không nhận được khóa. Chúng đưa bạn tới một trang BombVault, nơi bạn đăng nhập bằng mật khẩu đăng nhập và cho phép chúng. Chúng gọi BombVault từ máy chủ riêng, nên BombVault phải truy cập được từ internet ở địa chỉ công khai bên dưới, với chứng chỉ mà trình duyệt tin cậy. Tắt nó sẽ đăng xuất mọi ứng dụng khách.",
  "mcp.oauthNeedsPassword": "Hãy đặt mật khẩu đăng nhập trước. Trang đăng nhập sẽ hỏi mật khẩu này.",
