  "receiver.server.intro": "Cho phép các đối tác sao chép bản sao lưu off-site của họ vào máy này. BombVault khởi động một rest-server ở chế độ append-only tại đây và cung cấp nó cho các phiên bản trong nhóm của bạn.",
