  "recovery.foreignNoDefinition": "Bản sao này không có định nghĩa của {name}, nên BombVault không thể tạo lại nó từ đây. Các định nghĩa nằm trong bản sao lưu cài đặt của máy chủ cũ. Hãy khôi phục bản đó trong trình hướng dẫn khẩn cấp, rồi khôi phục {name} ở đó.",
