  "repos.locationLocked": "Không thể dời vị trí khi vẫn còn thứ gì sao lưu về đây: mọi thứ đã ghi vẫn nằm nguyên, nên lần sao lưu kế tiếp sẽ thành công vào một kho rỗng. Hãy thêm kho thứ hai và trỏ các mục sang đó.",
