  "placementCode.repoGone": "Kho từng ở đây đã mất, hoặc ổ đĩa của nó chưa được gắn trên máy chủ. BombVault không tạo kho mới trống ở chỗ đó. Hãy gắn lại ổ đĩa, hoặc tạo kho mới ở đây nếu bạn đã cố ý làm trống kho cũ.",
  "placementCode.destinationHoldsBackups": "Không thể chuyển vị trí khi vẫn đang sao lưu vào đây: mọi thứ đã ghi đến giờ sẽ bị bỏ lại, và lần sao lưu tiếp theo sẽ gặp một kho trống. Hãy thêm một đích sao lưu thứ hai và chuyển các mục sang đó.",
  "placementCode.backupsNotThere": "Các bản sao lưu lưu ở đây không mở được qua kết nối đã đổi, nên chưa có gì được lưu. Hãy kiểm tra những gì bạn đã nhập. Nếu các bản sao lưu đã được chuyển đi, hãy thêm một đích sao lưu thứ hai cho nơi mới.",
  "placementCode.lastCopies": "Một số mục sẽ mất bản sao lưu duy nhất của chúng, và danh sách đã thay đổi kể từ khi hiển thị. Kiểm tra lại.",
  "placementCode.nothingToErase": "Không bản sao lưu nào ở đây có thể xóa được. Thay vào đó, hãy xóa đích sao lưu và giữ lại các bản sao lưu.",
  "placementCode.homeNeeded": "Hãy chọn thư mục mà các phần sẽ chuyển tới.",
  "placementCode.homeSame": "Các phần đã ở trong thư mục đó. Hãy chọn thư mục khác.",
