  "placementCode.ownFolderUnreadable": "Không đọc được các bản sao lưu trong thư mục riêng cũ, nên không thể sao chép chúng. Hãy kiểm tra ổ đĩa đã được gắn hoặc nơi đó có phản hồi, rồi thử lại.",
