  "anomaly.acknowledgeHint": "Đánh dấu bất thường này là đã xem và đóng lại. Chừng nào nguyên nhân còn đó thì không báo lại; khi nguyên nhân đã mất rồi quay lại thì có báo. Nếu bất thường này đang giữ các bản sao lưu cũ, chúng sẽ lại bị xóa từ lần dọn dẹp tới. Nếu thay đổi là có chủ ý, đánh dấu là đã lường trước sẽ tốt hơn.",
  "anomaly.expectedHint": "Cho BombVault biết thay đổi là có chủ ý. Một kích thước hoặc thời lượng mới trở thành mức bình thường sau 10 bản sao lưu nữa, trong khi phép kiểm tra nguồn gần như rỗng vẫn bật. Với dữ liệu mới, các lượng cho đến mức này sẽ không còn được báo cho mục này. Nếu bất thường này đang giữ các bản sao lưu cũ, chúng sẽ lại bị xóa từ lần dọn dẹp tới.",
