  "anomaly.sentence.newData": "{name} đã thêm {bytes} dữ liệu mới trong một bản sao lưu. Thường thì nhiều nhất là {typical}.",
  "anomaly.sentence.newDataRewrite": "{name} đã ghi lại {bytes} trong một bản sao lưu, ít nhất một nửa tất cả những gì được sao lưu ({source}). Nếu bạn không thay đổi nhiều đến vậy, hãy kiểm tra xem tệp có bị mã hóa hay thay thế không.",
  "anomaly.sentence.newDataRenamed": "Mọi tệp của {name} trông như mới dù đã có bản sao lưu cũ hơn, và {bytes} trong {source} được lưu lại. Tệp bị đổi tên và ghi lại cùng lúc là dấu hiệu điển hình của mã độc tống tiền. Hãy kiểm tra tệp trước tiên.",
