  "anomaly.settings.title": "Bất thường",
  "anomaly.settings.hint": "So sánh mỗi bản sao lưu của một mục với lịch sử của chính mục đó và báo những gì không khớp. Chạy nền sau mỗi lần sao lưu và không làm chậm lần nào. Hầu hết các kiểm tra bắt đầu sau 10 bản sao lưu của một mục; lỗi, việc ghi lại phần lớn dữ liệu và nguồn gần như trống được kiểm tra ngay từ đầu. Dung lượng trống được theo dõi cho kho lưu trữ cục bộ và các kho rclone có báo dung lượng; trên chia sẻ người dùng của Unraid đó là dung lượng trống của cả mảng.",
