  "entry.hostSilent.vm": "libvirt không phản hồi. Trang này hiển thị các bản sao lưu và cài đặt mà BombVault lưu cho VM. Trạng thái và các thao tác trên VM đang chạy sẽ trở lại khi libvirt phản hồi.",
