  "storage.flow.title": "Đích theo phần",
  "storage.flow.hint": "Mặc định của từng phần. Trong biểu đồ, mỗi đường là một công tắc: bấm vào đường hoặc điểm sẽ bật hay tắt nó. Đường nét đứt là đang tắt. Dưới \"Công tắc\" bạn đặt điều tương tự bằng các nút. Công tắc quyết định các bản sao lưu mới đi đâu. Các mục theo mặc định sẽ chuyển theo ngay, nên bản sao lưu kế tiếp của chúng đi đến các đích mới. Các bản sao lưu đã lưu rồi vẫn ở nguyên chỗ cũ và bạn vẫn có thể khôi phục chúng từ đó. Các mục đã chọn đích riêng trên trang của mình thì giữ nguyên. Quy tắc riêng của một phần, chẳng hạn thời gian giữ, nén hoặc một địa chỉ riêng, được đặt trên trang của đích.",
