  "whatsNew.showAll": "Hiện lại tất cả",
  "whatsNew.markAll": "Đánh dấu tất cả là đã xem",
  "whatsNew.go": "Đi tới đó",
  "whatsNew.absent": "Hiện không có trên trang của nó",
  "whatsNew.way": "Lối đi tới {n} thay đổi:",
  "whatsNew.page.entry": "Trang của một mục",
  "whatsNew.page.location": "Trang của một đích sao lưu",
  "whatsNew.page.none": "Chạy nền",
  "whatsNew.windowTitleSince": "Mới từ {version}",
  "whatsNew.overviewHead": "Chấm xanh đánh dấu những gì mới. Nhấp sẽ ẩn chấm, và tất cả nằm ở Cài đặt, Thông tin.",
  "whatsNew.overviewCustomize": "Tổng quan bắt đầu với năm thẻ. Các thẻ khác nằm dưới “Tùy chỉnh”, và thẻ nào cũng có thể di chuyển, đổi kích thước và ẩn đi.",
  "whatsNew.overviewDecline": "“Không sao lưu” gỡ một mục khỏi danh sách này khi bạn cố ý bỏ qua nó. Sau đó nó không còn bị tính là chưa được bảo vệ.",
  "whatsNew.overviewInstances": "Trong ứng dụng Android, đầu phần tổng quan hiển thị tên phiên bản bạn đang dùng. Mũi tên trước tên đưa bạn về tổng quan của ứng dụng, nơi liệt kê mọi phiên bản của bạn.",
  "whatsNew.backupsTiles": "Mọi thứ được sao lưu nằm trong một danh sách. Các ô chọn một loại.",
  "whatsNew.backupsBar": "“Bộ lọc”, “Sắp xếp” và “Tìm kiếm” là ba nút phía trên danh sách.",
  "whatsNew.backupsRow": "Mỗi dòng chỉ hiện một trạng thái, phần còn lại nằm trong bong bóng bên cạnh tên. Chọn dòng như chọn tệp: Ctrl+nhấp, Shift+nhấp hoặc nhấn giữ.",
  "whatsNew.backupsActions": "Hành động chính của trang nổi ở góc dưới bên phải. “Thêm” chứa những hành động ít dùng.",
  "whatsNew.entryPage": "Mỗi mục có một trang riêng với ba tab: Bản sao lưu, Cài đặt và Xác minh.",
  "whatsNew.entryDefaults": "Một mục theo lịch trình và đích sao lưu mặc định cho đến khi bạn đặt riêng cho nó ở đây.",
  "whatsNew.restoreTiles": "“Khôi phục” là một trang cho mọi thứ. Chọn một phần hoặc tìm một mục, rồi chọn một bản sao lưu trên dòng thời gian của nó.",
  "whatsNew.restoreWhere": "Một cửa sổ hỏi khôi phục gì và về đâu. “Bên cạnh bản gốc” đưa một bản sao trở lại và để bản gốc nguyên như cũ.",
  "whatsNew.restoreMany": "Chọn nhiều mục bằng Ctrl+nhấp, Shift+nhấp hoặc nhấn giữ, rồi khôi phục cùng nhau, lần lượt từng mục.",
  "whatsNew.restoreEmergency": "Trình hướng dẫn khẩn cấp bắt đầu từ đây. Nó đưa một máy chủ đã mất hoặc được thiết lập lại trở về, qua bốn bước.",
  "whatsNew.anomaliesTiles": "Các ô chọn mức độ nghiêm trọng. “Đang mở” hoặc “Đã đóng” chọn danh sách.",
  "whatsNew.anomaliesRings": "Một vòng cho mỗi mục cho thấy phát hiện đã học được đến đâu điều gì là bình thường.",
  "whatsNew.storageList": "Các đích sao lưu cục bộ và off-site nằm trong một danh sách. Mỗi đích sao lưu có một trang riêng.",
  "whatsNew.storageFlow": "3-2-1 dưới dạng hình ảnh. Mỗi đường nối từ một phần tới một đích sao lưu là một công tắc, kể cả Cục bộ, và một lần bấm sẽ bật hoặc tắt nó. Mỗi phần cho biết có bao nhiêu mục của nó được sao lưu đến nơi khác.",
  "whatsNew.locationKeep": "Lưu giữ là “Ngắn”, “Cân bằng”, “Dài” hoặc giá trị riêng của bạn. Dòng thời gian cho thấy một quy tắc giữ lại những bản sao lưu nào.",
  "whatsNew.locationMove": "“Di chuyển” đưa bản sao của một phần sang đích sao lưu khác, cùng toàn bộ lịch sử.",
  "whatsNew.instancesPair": "Các phiên bản được ghép nối bằng mười hai từ. Sau đó mỗi cái hiển thị vai trò của mình dưới dạng ô.",
  "whatsNew.instancesPhones": "Điện thoại được ghép nối qua ứng dụng Android có một thẻ riêng bên cạnh các phiên bản.",
  "whatsNew.settingsTiles": "Cài đặt gồm mười bốn ô. Nhấn / hoặc Ctrl+K để tìm trong tất cả, kể cả theo tên cũ của các trang.",
  "whatsNew.settingsPin": "Đích sao lưu và Phiên bản là các ô cài đặt. Công tắc này ghim chúng vào thanh bên.",
  "whatsNew.settingsWeek": "Tuần dưới dạng một dải, với mỗi lần chạy đã lên lịch từ thứ Hai đến Chủ nhật.",
  "whatsNew.pairingSteps": "Ba thẻ cho thấy cách ghép nối hoạt động. Bên dưới, relay có bốn dạng, mỗi dạng kèm hình minh họa riêng.",
  "whatsNew.settingsVersion": "Thông tin gồm Phiên bản, Trợ giúp và Giới thiệu. Phiên bản liệt kê BombVault, GlimStone, restic và rclone. Nút Mới trong đó mở danh sách thay đổi, hoặc ghi chú phát hành khi bạn đã xem hết.",
  "whatsNew.settingsManual": "Nút màu vàng bên dưới Trợ giúp mở phần hướng dẫn.",
  "whatsNew.lookGlyphs": "Góc và Hoạt ảnh hiển thị một biểu tượng cho từng lựa chọn, giống như Giao diện.",
